import axiosInstance from "../api/axios";
import { showToast } from "../utils/ToastUtil"; // Importing the showToast function
import { AxiosError } from "axios"; // Import AxiosError from axios package

// Register user
export const registerUser = async (user: {
  username: string;
  email: string;
  password: string;
  first_name: string;
  last_name: string;
  gender: string;
}) => {
  try {
    const response = await axiosInstance.post(`/users/`, user);
    return response.data;
  } catch (error) {
    // Type Guard to check if the error is an AxiosError
    if (error instanceof AxiosError) {
      const errorMessage = error.response?.data?.detail || "An error occurred during registration.";
      showToast(errorMessage, false); // Display error toast
      console.error("Error registering user:", errorMessage);
    } else {
      showToast("An unknown error occurred.", false);
      console.error("Unknown error occurred during registration:", error);
    }
    throw error; // Re-throw error to handle it further up the chain if needed
  }
};

// Get list of users paginated
export const getUsers = async (page: number, size: number) => {
  try {
    const response = await axiosInstance.get(`/users?page=${page}&size=${size}`);
    return response.data;
  } catch (error) {
    // Type Guard to check if the error is an AxiosError
    if (error instanceof AxiosError) {
      const errorMessage = error.response?.data?.detail || "An error occurred while fetching users.";
      showToast(errorMessage, false); // Display error toast
      console.error("Error fetching users:", errorMessage);
    } else {
      showToast("An unknown error occurred.", false);
      console.error("Unknown error occurred while fetching users:", error);
    }
    throw error; // Re-throw error to handle it further up the chain if needed
  }
};

// Login user (JWT authentication)
export const loginUser = async (username: string, password: string) => {
  try {
    const response = await axiosInstance.post(`/login/`, { username, password });
    return response.data.access_token;
  } catch (error) {
    // Type Guard to check if the error is an AxiosError
    if (error instanceof AxiosError) {
      const errorMessage = error.response?.data?.detail || "Invalid credentials or server error.";
      showToast(errorMessage, false); // Display error toast
      console.error("Error logging in:", errorMessage);
    } else {
      showToast("An unknown error occurred.", false);
      console.error("Unknown error occurred during login:", error);
    }
    throw error; // Re-throw error to handle it further up the chain if needed
  }
};

// Health check API
export const checkApiHealth = async () => {
  try {
    const response = await axiosInstance.get(`/healthcheck`);
    return response.data.status;
  } catch (error) {
    // Type Guard to check if the error is an AxiosError
    if (error instanceof AxiosError) {
      showToast("Unable to reach API. Please try again later.", false); // Display error toast
      console.error("Error checking API health:", error.message);
    } else {
      showToast("An unknown error occurred.", false);
      console.error("Unknown error occurred during health check:", error);
    }
    throw error; // Re-throw error to handle it further up the chain if needed
  }
};
